<template><admin-layout><Head :title="$t(&quot;UMI 运营 · Deepro&quot;)"/><main class="ufc">
  <header><div><small>DEEPRO / UMI</small><h1>{{ $t("UMI 运营中心") }}</h1><p>{{ $t("资金池、链上销毁、收益结算与成员记录。") }}</p></div></header>
  <div :class="['ufc-status',data.readiness.ready?'ready':'waiting']"><b>{{data.readiness.ready?$t('接入已就绪'):$t('接入准备中')}}</b><span v-if="!data.readiness.ready">{{ $t("待完成：") }}{{data.readiness.issues.map(issue).join('、')}}</span></div>
  <div class="ufc-kpis"><article><small>{{ $t("累计链上销毁") }}</small><b>{{fmt(data.burn.confirmed_umi)}} UMI</b></article><article><small>{{ $t("过去 24 小时") }}</small><b>{{fmt(data.burn.past_24h_umi)}} UMI</b></article><article><small>{{ $t("待销毁") }}</small><b>{{fmt(data.burn.pending_umi)}} UMI</b></article><article><small>{{ $t("有效轮次") }}</small><b>{{data.active_cycle_total}}</b></article></div>
  <p v-if="error" class="ufc-error" role="alert">{{ $t(error) }}</p><p v-if="message" class="ufc-ok" role="status">{{ $t(message) }}</p>
  <nav><button v-for="t in visibleTabs" :key="t.key" :class="{active:tab===t.key}" @click="selectTab(t.key)">{{ $t(t.label) }}</button></nav>
  <div v-if="tab==='operations'" class="ufc-grid"><section class="ufc-card"><h2>{{ $t("每日结算") }}</h2><p>{{ $t("静态按本金，团队按级差和平级，推荐按直推充值计算。按 UTC+8 已结束业务日依次结算，不可跳日；日率按业务日有效版本执行。") }}</p><label>{{ $t("业务日期") }}<input v-model="day" type="date" readonly></label><label>{{ $t("静态日率") }}<input v-model.trim="dayRate" readonly inputmode="decimal" placeholder="0.008–0.015"></label><button v-if="canAction('day')" :disabled="busy || !data.readiness.ready || !data.settlement_calendar?.due || data.settlement_calendar?.historical_gap || data.settlement_calendar?.rate_unverified" @click="send('day',{business_date:day,static_rate:dayRate})">{{ $t("执行结算") }}</button></section><section class="ufc-card"><h2>{{ $t("现货资金划入") }}</h2><p>{{ $t("UMI 充值及提现补款仅接受 Deepro 现货可用余额划入。挂单冻结余额不参与扣款。") }}</p><a href="/exchange-control-panel/umi/operations?tab=records&amp;record_dataset=wallet_moves">{{ $t("查看账户划转凭证 ›") }}</a></section></div>
<section v-if="tab==='operations' && data.recovery" class="ufc-card"><h2>{{ $t("异常恢复") }}</h2><p>{{ $t("已确认销毁待补积分") }} {{data.recovery.missing_points}} {{ $t("· 超过一小时未确认销毁") }} {{data.recovery.stale_burns}} {{ $t("· 等待补款") }} {{data.recovery.awaiting_topup}}</p><p v-if="data.settlement_calendar?.historical_gap" role="alert">{{ $t("存在已结日期之前的历史缺日，请先独立核对，不自动重写已入账收益。") }}</p><p v-if="data.settlement_calendar?.rate_unverified" role="alert">{{ $t("缺少该历史业务日的已核定日率快照，请先核对历史规则。") }}</p><p>{{ $t("积分任务每五分钟检查一次；缺少历史报价时按小时重试。只使用原销毁确认时间的证据，资料恢复后可手动重试。") }}</p><a href="/exchange-control-panel/umi/operations?tab=records&amp;record_dataset=recovery">{{ $t("全部恢复任务与导出") }}</a><div class="ufc-scroll"><table><tr><th>ID</th><th>{{ $t("成员") }}</th><th>{{ $t("销毁") }}</th><th>{{ $t("状态") }}</th><th>{{ $t("尝试次数") }}</th><th>{{ $t("最近尝试") }}</th><th>{{ $t("操作") }}</th></tr><tr v-for="r in data.recovery.tasks" :key="r.id"><td>{{r.id}}</td><td>{{r.member_id}}</td><td>{{r.reference_id}}</td><td>{{r.status}} {{r.error_code}}</td><td>{{r.attempts}}</td><td>{{date(r.last_attempt_at)}}</td><td><button v-if="(r.status!=='resolved') && canAction('recover_points')" :disabled="busy" @click="send('recover_points',{task_id:r.id})">{{ $t("核对证据并重试") }}</button></td></tr></table></div></section>
  <div v-if="tab==='burn'" class="ufc-card"><h2>{{ $t("销毁任务") }}</h2><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=lots">{{ $t("查询全部记录与导出 ›") }}</a><p>{{ $t("逐笔提交托管审批；链上转入黑洞并达到确认数后，才能更新为已销毁。待处理任务可在托管台审批。") }}</p><div class="ufc-scroll"><table><thead><tr><th>ID</th><th>{{ $t("来源") }}</th><th>UMI</th><th>{{ $t("状态") }}</th><th>{{ $t("托管任务") }}</th><th>{{ $t("操作") }}</th></tr></thead><tbody><tr v-for="l in data.lots" :key="l.id"><td>{{l.id}}</td><td>{{ $t(purpose(l.purpose)) }}</td><td>{{fmt(l.amount_umi)}}</td><td>{{l.status}}</td><td>{{l.custody_transfer_id||'—'}}</td><td><button v-if="(l.status==='pending') && canAction('queue_burn')" :disabled="busy || !data.readiness.ready" @click="send('queue_burn',{lot_id:l.id})">{{ $t("提交托管") }}</button><button v-else-if="(l.status==='custody') && canAction('sync_burn')" :disabled="busy" @click="send('sync_burn',{lot_id:l.id})">{{ $t("核验链上") }}</button><span v-else>—</span></td></tr></tbody></table></div><a v-if="($page.props.adminAllowedRoutes||[]).includes('admin.custody')" href="/exchange-control-panel/custody">{{ $t("前往托管审批 ›") }}</a></div>
  <div v-if="tab==='members'" class="ufc-card"><h2>{{ $t("UMI 用户管理") }}</h2><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=members">{{ $t("全部成员、分页筛选与用户全景 ›") }}</a><p>{{ $t("共") }} {{data.member_total}} {{ $t("位成员；原用户沿用原邀请关系，未绑定上级的原档案会保留待接续标记。") }}</p><form class="ufc-search" @submit.prevent="searchMembers"><input v-model.trim="memberSearch" :placeholder="$t(&quot;成员邀请码、原 UID 或 Deepro 用户 ID&quot;)"><button>{{ $t("查找") }}</button></form><div class="ufc-scroll"><table><thead><tr><th>{{ $t("成员") }}</th><th>{{ $t("Deepro 用户") }}</th><th>{{ $t("等级") }}</th><th>{{ $t("UMI 邀请码") }}</th><th>{{ $t("原 UMI 关系") }}</th></tr></thead><tbody><tr v-for="m in data.members" :key="m.id"><td>{{m.id}}</td><td>{{m.user_id}}</td><td>V{{m.level}}</td><td>{{m.member_code}}</td><td>{{m.legacy_link_status==='pending'?$t('上级待接续'):m.legacy_link_status==='resolved'?$t('已接续'):'—'}}</td></tr></tbody></table></div><h3>{{ $t("原 UMI 用户待开通") }}</h3><p>{{ $t("已核验旧账户可自行开通，也可由管理员核对后激活。") }}</p><div class="ufc-search"><input v-model.trim="legacyUserId" inputmode="numeric" :placeholder="$t(&quot;输入 Deepro 用户 ID&quot;)"><button v-if="canAction('activate_legacy')" :disabled="busy || !legacyUserId" @click="send('activate_legacy',{user_id:legacyUserId})">{{ $t("核对激活") }}</button></div><div class="ufc-scroll"><table><thead><tr><th>{{ $t("原 UID") }}</th><th>{{ $t("Deepro 用户") }}</th><th>{{ $t("原上级 UID") }}</th><th>{{ $t("操作") }}</th></tr></thead><tbody><tr v-for="m in data.legacy_candidates" :key="m.user_id"><td>{{m.legacy_id||'—'}}</td><td>{{m.user_id}}</td><td>{{m.parent_legacy_id||'—'}}</td><td><button v-if="canAction('activate_legacy')" :disabled="busy" @click="send('activate_legacy',{user_id:m.user_id})">{{ $t("核对激活") }}</button></td></tr></tbody></table></div><h3>{{ $t("最近轮次") }}</h3><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=cycles">{{ $t("查询全部记录与导出 ›") }}</a><div class="ufc-scroll"><table><thead><tr><th>{{ $t("轮次") }}</th><th>{{ $t("成员") }}</th><th>{{ $t("本金 UMI") }}</th><th>{{ $t("总额度 UMI") }}</th><th>{{ $t("已释放 UMI") }}</th><th>{{ $t("状态") }}</th></tr></thead><tbody><tr v-for="c in data.cycles" :key="c.id"><td>{{c.id}}</td><td>{{c.member_id}}</td><td>{{fmt(c.principal_umi)}}</td><td>{{fmt(c.cap_umi)}}</td><td>{{fmt(c.released_umi)}}</td><td>{{c.status}}</td></tr></tbody></table></div></div>
  <div v-if="tab==='stock'" class="ufc-grid"><section class="ufc-card"><h2>{{ $t("盈证国际价格参考份额") }}</h2><p>{{ $t("股票积分获取满 60 天自动确权转为 UMI 参考份额余额；确权后锁定 90 天，到期变为可划转份额。每次变动都有独立流水。") }}</p><div class="ufc-status" :class="data.stock_audit?.ok?'ready':'waiting'"><b>{{data.stock_audit?.ok?$t('份额对账一致'):$t('份额需要核对')}}</b><span>{{ $t("已确权") }} {{fmt(data.stock_audit?.issued_shares)}} {{ $t("份 · 已核销") }} {{fmt(data.stock_audit?.written_off_shares)}} {{ $t("份 · 已转交易账户") }} {{fmt(data.stock_audit?.exported_shares)}} {{ $t("份 · 当前持有") }} {{fmt(data.stock_audit?.held_shares)}} {{ $t("份") }}</span></div><button v-if="canAction('stock_settle')" :disabled="busy" @click="send('stock_settle',{})">{{ $t("核对到期权益") }}</button><p>{{ $t("本产品为站内价格参考份额，不代表上市公司股东登记或外部证券持仓。") }}</p><p v-if="data.stock_coverage">{{ $t("账面应付") }} {{fmt(data.stock_coverage.total_obligation)}} {{ $t("份 · 池内可用") }} {{fmt(data.stock_coverage.pool_available)}} {{ $t("份 · 缺口") }} {{fmt(data.stock_coverage.shortfall)}} {{ $t("份") }}</p><h3>{{ $t("近期权益") }}</h3><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=points">{{ $t("查询全部记录与导出 ›") }}</a><div class="ufc-scroll"><table><thead><tr><th>{{ $t("积分") }}</th><th>{{ $t("成员") }}</th><th>{{ $t("份额数") }}</th><th>{{ $t("确权日期") }}</th><th>{{ $t("解锁日期") }}</th><th>{{ $t("状态") }}</th></tr></thead><tbody><tr v-for="t in data.stock_terms" :key="t.point_entry_id"><td>{{t.point_entry_id}}</td><td>{{t.member_id}}</td><td>{{fmt(t.delta_points)}}</td><td>{{date(t.eligible_at)}}</td><td>{{date(t.unlock_at)}}</td><td>{{ $t(stockStatus(t.status)) }}</td></tr></tbody></table></div><h3>{{ $t("成员份额") }}</h3><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=stock_accounts">{{ $t("查询全部记录与导出 ›") }}</a><div class="ufc-scroll"><table><thead><tr><th>{{ $t("成员") }}</th><th>{{ $t("锁定") }}</th><th>{{ $t("可划转") }}</th></tr></thead><tbody><tr v-for="a in data.stock_accounts" :key="a.member_id"><td>{{a.member_id}}</td><td>{{fmt(a.locked_shares)}}</td><td>{{fmt(a.available_shares)}}</td></tr></tbody></table></div></section><section class="ufc-card"><h2>{{ $t("管理员站内划转与核销") }}</h2><p>{{ $t("仅可操作已解锁份额；请输入实际原因，提交后无法删除流水。") }}</p><label>{{ $t("操作") }}<select v-model="stockAction"><option value="stock_transfer">{{ $t("站内划转") }}</option><option value="stock_writeoff">{{ $t("核销") }}</option></select></label><label>{{ $t("转出成员 ID") }}<input v-model.trim="stockFrom" inputmode="numeric"></label><label v-if="stockAction==='stock_transfer'">{{ $t("转入成员 ID") }}<input v-model.trim="stockTo" inputmode="numeric"></label><label>{{ $t("份额数") }}<input v-model.trim="stockShares" inputmode="decimal"></label><label>{{ $t("操作依据") }}<input v-model.trim="stockReason" :placeholder="$t(&quot;请填写至少十个字的依据&quot;)"></label><button v-if="capabilities.stock" :disabled="busy || !stockFrom || !stockShares || stockReason.length<10 || (stockAction==='stock_transfer'&&!stockTo)" @click="send(stockAction,{from_member_id:stockFrom,to_member_id:stockAction==='stock_transfer'?stockTo:null,shares:stockShares,reason:stockReason})">{{ $t("确认") }}{{stockAction==='stock_transfer'?$t('划转'):$t('核销')}}</button><h3>{{ $t("份额流水") }}</h3><div class="ufc-scroll"><table><thead><tr><th>{{ $t("记录") }}</th><th>{{ $t("操作") }}</th><th>{{ $t("转出") }}</th><th>{{ $t("转入") }}</th><th>{{ $t("Deepro 用户") }}</th><th>{{ $t("份额数") }}</th><th>{{ $t("管理员") }}</th><th>{{ $t("时间") }}</th></tr></thead><tbody><tr v-for="m in data.stock_moves" :key="m.id"><td>{{m.id}}</td><td>{{ $t(stockMove(m.kind)) }}</td><td>{{m.from_member_id||'—'}}</td><td>{{m.to_member_id||'—'}}</td><td>{{m.exchange_user_id||'—'}}</td><td>{{fmt(m.shares)}}</td><td>{{m.actor_id||$t('系统')}}</td><td>{{date(m.created_at)}}</td></tr></tbody></table></div></section></div>
  <div v-if="tab==='orders'" class="ufc-card"><h2>{{ $t("充值与提现 · 近期记录") }}</h2><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=withdrawals">{{ $t("查看全部订单及导出 ›") }}</a><h3>{{ $t("充值订单") }}</h3><div class="ufc-scroll"><table><thead><tr><th>ID</th><th>{{ $t("成员") }}</th><th>{{ $t("来源") }}</th><th>UMI</th><th>{{ $t("状态") }}</th><th>{{ $t("轮次") }}</th></tr></thead><tbody><tr v-for="i in data.intents" :key="i.id"><td>{{i.id}}</td><td>{{i.member_id}}</td><td>{{i.source}}</td><td>{{fmt(i.amount_umi)}}</td><td>{{i.status}}</td><td>{{i.cycle_id||'—'}}<template v-if="i.status==='pending_burn'"><input v-model.trim="cancelReasons[i.id]" :placeholder="$t(&quot;退回依据（至少十字）&quot;)"><button v-if="canAction('cancel_intake')" :disabled="busy || (cancelReasons[i.id]||'').length<10" @click="send('cancel_intake',{intent_id:i.id,reason:cancelReasons[i.id]})">{{ $t("核对并退回未托管充值款") }}</button></template></td></tr></tbody></table></div><h3>{{ $t("提现订单") }}</h3><div class="ufc-scroll"><table><thead><tr><th>ID</th><th>{{ $t("成员") }}</th><th>{{ $t("到账 UMI") }}</th><th>{{ $t("额外 30%") }}</th><th>{{ $t("已销毁") }}</th><th>{{ $t("状态") }}</th></tr></thead><tbody><tr v-for="w in data.withdrawals" :key="w.id"><td>{{w.id}}</td><td>{{w.member_id}}</td><td>{{fmt(w.requested_umi)}}</td><td>{{fmt(w.required_burn_umi)}}</td><td>{{fmt(w.confirmed_burn_umi)}}</td><td>{{w.status}}</td></tr></tbody></table></div></div>
  <section v-if="tab==='cutover' && cutover" class="ufc-card">
<h2>{{ $t("采集批次与差异核验") }}</h2><p>{{ $t("暂存数据保留完整来源，只有账户、身份、原上级及每项余额均核对一致后才能核定。核定记录与接续凭证不可覆盖。") }}</p>
<p v-if="!cutover.source_batch">{{ $t("尚无采集批次。请由管理员通过受控导入命令暂存已校验的数据包。") }}</p>
<div v-if="captureBatches"><div class="ufc-scroll"><table><thead><tr><th>{{ $t("批次") }}</th><th>{{ $t("成员数") }}</th><th>{{ $t("核对本金 UMI") }}</th><th>{{ $t("采集完成时间") }}</th><th>{{ $t("操作") }}</th></tr></thead><tbody><tr v-for="b in captureBatches.data" :key="b.id"><td>#{{b.id}}</td><td>{{b.member_count}}</td><td>{{fmt(b.principal_umi)}}</td><td>{{date(b.finished_at)}}</td><td><a :href="'/exchange-control-panel/umi/operations?tab=cutover&batch_id='+b.id">{{ $t("核对本批次") }}</a></td></tr></tbody></table></div><div class="ufc-pages"><a v-if="captureBatches.prev_page_url" :href="captureBatches.prev_page_url">{{ $t("上一页") }}</a><span>{{ $t("共") }} {{captureBatches.total}} {{ $t("个批次") }}</span><a v-if="captureBatches.next_page_url" :href="captureBatches.next_page_url">{{ $t("下一页") }}</a></div></div>
<div v-if="cutover.source_batch"><p>{{ $t("当前批次 #") }}{{cutover.source_batch.id}} {{ $t("· 清单") }} {{cutover.source_batch.manifest_sha256}}</p><p v-if="!cutover.latest_batch" class="ufc-error">{{ $t("已有更新的采集批次，请选择最新批次核对。") }}</p><p>{{ $t("采集窗口") }} {{date(cutover.source_batch.started_at)}} {{ $t("至") }} {{date(cutover.source_batch.finished_at)}}{{ $t("。在线采集不是同一瞬间的数据库快照，复核时须核定业务截止点。") }}</p>
<details v-if="cutover.differences?.length" open><summary>{{ $t("待核对") }} {{cutover.blocked}} {{ $t("个账户") }}</summary><div class="ufc-scroll ufc-differences"><table><thead><tr><th>{{ $t("原 UID") }}</th><th>{{ $t("业务账户") }}</th><th>{{ $t("本地本金") }}</th><th>{{ $t("采集本金") }}</th><th>{{ $t("差异") }}</th></tr></thead><tbody><tr v-for="(d,index) in cutover.differences" :key="index"><td>{{d.legacy_id||$t('未绑定')}}</td><td>{{d.account_id||$t('缺失')}}</td><td>{{fmt(d.principal_umi)}}</td><td>{{fmt(d.source_principal_umi)}}</td><td>{{d.issues.map(captureIssue).join('；')}}</td></tr></tbody></table></div></details>
<p v-if="cutover.approved">{{ $t("已由管理员") }} {{cutover.approval.actor_id}} {{ $t("核定；业务截止") }} {{date(cutover.approval.cutoff_at)}}。</p>
<template v-else><label>{{ $t("核定业务截止时间（UTC+8）") }}<input type="datetime-local" v-model="captureCutoff"></label><label>{{ $t("复核依据") }}<input v-model.trim="captureReason" :placeholder="$t(&quot;填写来源、截止点及差异处理依据&quot;)"></label><button :disabled="busy || cutover.blocked>0 || !cutover.latest_batch || !captureCutoff || captureReason.length<10" @click="send('approve_snapshot',{batch_id:cutover.source_batch.id,source_sha256:cutover.sha256,cutoff_at:new Date(captureCutoff+':00+08:00').toISOString(),reason:captureReason})">{{ $t("核定采集来源") }}</button><p>{{ $t("由暂存操作人之外的管理员复核；资料或余额变化后必须重新核对。") }}</p></template></div>
<h2>{{ $t("账户本金接续") }}</h2><p>{{ $t("先导入并核对全新数据，再执行一次性接续。账户中的 UMI 余额合并为充值本金，历史账务与邀请关系继续在本中心查询。低于 100 USDT 的本金待补足后激活。历史提现销毁积分另行核对，本操作不补发积分。") }}</p><div class="ufc-status waiting"><b>{{ $t("待接续") }} {{cutover.accounts}} {{ $t("个账户") }}</b><span>{{ $t("本金") }} {{fmt(cutover.principal_umi)}} {{ $t("UMI · 待核对") }} {{cutover.blocked}} {{ $t("个账户") }}</span></div><p>{{ $t("数据摘要：") }}{{cutover.sha256}}</p><label>{{ $t("已确认 UMI 报价 ID") }}<input v-model.trim="cutoverQuote" inputmode="numeric"></label><label>{{ $t("收益起算日") }}<input v-model="cutoverStart" type="date"></label><label><input v-model="cutoverConfirmed" type="checkbox">{{ $t("我已核对全新数据、报价及起算日，确认将余额一次性转为充值本金") }}</label><button :disabled="busy || !cutover.approved || !cutover.latest_batch || !data.settings.account_cutover_enabled || !cutoverConfirmed || !cutoverQuote || !cutoverStart || cutover.blocked>0 || cutover.accounts===0" @click="send('account_cutover',{batch_id:cutover.source_batch.id,source_sha256:cutover.sha256,quote_id:cutoverQuote,starts_on:cutoverStart})">{{ $t("确认接续") }}</button><p v-if="!data.settings.account_cutover_enabled">{{ $t("请在配置中开启账户本金接续。") }}</p></section>
  <account-history v-if="tab==='archive' && accountHistory" :portfolio="accountHistory" :section="accountSection" :admin-view="true"/>
  <div v-if="tab==='settings'" class="ufc-grid"><section v-if="capabilities.settings" class="ufc-card"><h2>{{ $t("资金与链上配置") }}</h2><p>{{ $t("可先保存配置，业务开关默认关闭。开启充值、结算或提现前，系统会检查真实资金池、Deepro BSC 网络映射与托管通道；开启股票划转还需准备 HK08379 可用份额。") }}</p><p v-if="!data.readiness.ready">{{ $t("待完成：") }}{{data.readiness.issues.map(issue).join('、')}}</p><label>{{ $t("Deepro 资金池用户 ID") }}<input v-model.trim="poolUserId" inputmode="numeric"></label><label>{{ $t("BSC 网络（复用 Deepro 配置）") }}<input :value="data.settings?.umi_network_id ? 'BEP20 · 网络 ID '+data.settings.umi_network_id : '现有网络配置待核对'" readonly></label><label>{{ $t("专属销毁发送地址") }}<input v-model.trim="dedicatedAddress" maxlength="42" placeholder="0x…"></label><label><input v-model="accountCutoverEnabled" type="checkbox">{{ $t("允许账户本金接续（仅在全新数据核对后开启）") }}</label><label><input v-model="intakeEnabled" type="checkbox">{{ $t("允许充值") }}</label><p>{{ $t("日率修改从下一个 UTC+8 业务日生效；历史欠结沿用该日原有效日率。有资金记录后不能直接更换资金池或发送地址。") }}</p><label>{{ $t("自动结算静态日率") }}<input v-model.trim="rate" inputmode="decimal" placeholder="0.008–0.015"></label><label><input v-model="settlementEnabled" type="checkbox">{{ $t("允许结算") }}</label><label><input v-model="withdrawalEnabled" type="checkbox">{{ $t("允许提现") }}</label><label><input v-model="stockTransferEnabled" type="checkbox">{{ $t("允许解锁份额转入 Deepro 交易账户") }}</label><p>{{ $t("转入前须准备好 HK08379 交易市场，以及资金池内相同数量的站内份额。") }}</p><button v-if="canAction('settings')" :disabled="busy" @click="send('settings',{revision:settingsRevision,pool_user_id:poolUserId||null,dedicated_address:dedicatedAddress,intake_enabled:intakeEnabled,settlement_enabled:settlementEnabled,settlement_rate:rate,withdrawal_enabled:withdrawalEnabled,stock_transfer_enabled:stockTransferEnabled,account_cutover_enabled:accountCutoverEnabled})">{{ $t("保存设置") }}</button><h3>{{ $t("销毁规则") }}</h3><p>{{ $t("销毁接收地址：") }}{{data.burn_address}}<br>{{ $t("终局存量：") }}{{fmt(data.terminal_supply_umi)}} UMI</p></section><section v-if="capabilities.quotes" class="ufc-card"><h2>{{ $t("UMI 盘口计价") }}</h2><p>{{ $t("采用 Deepro UMI/USDT 盘口卖一价；盘口为空或失效时暂停计价。") }}</p><p v-if="data.spot_quote?.available">{{fmt(data.spot_quote.quote.price)}} USDT · {{date(data.spot_quote.quote.observed_at)}}</p><p v-else>{{data.spot_quote?.message}}</p><button v-if="canAction('spot_quote')" :disabled="busy || !data.spot_quote?.available" @click="send('spot_quote',{})">{{ $t("保存卖一报价凭证") }}</button><h3>{{ $t("股票报价") }}</h3><p>{{ $t("股票积分报价限 72 小时内，须核对来源和时间。") }}</p><label>{{ $t("资产") }}<select v-model="asset"><option value="HK08379_USDT">08379 / USDT</option></select></label><label>{{ $t("价格") }}<input v-model.trim="price" inputmode="decimal"></label><label>{{ $t("来源") }}<input v-model.trim="source" :placeholder="$t(&quot;报价来源&quot;)"></label><label>{{ $t("来源编号") }}<input v-model.trim="sourceRef" :placeholder="$t(&quot;唯一编号&quot;)"></label><label>{{ $t("报价时间") }}<input v-model="observedAt" type="datetime-local"></label><button v-if="canAction('quote')" :disabled="busy" @click="send('quote',{asset,price,source,source_ref:sourceRef,observed_at:observedAt?new Date(observedAt).toISOString():null})">{{ $t("确认报价") }}</button><h3>{{ $t("近期报价") }}</h3><a href="/exchange-control-panel/umi/operations?tab=records&record_dataset=quotes">{{ $t("查询全部记录与导出 ›") }}</a><div v-for="q in data.quotes" :key="q.id" class="ufc-quote">{{q.asset}} · {{fmt(q.price)}} · {{q.source}} · {{q.observed_at}}</div></section></div>
