<section v-if="tab==='history' && history" class="ufc-card"><h2>{{ $t("账务记录") }}</h2><p>{{ $t("UMI 账户和") }} {{history.entry_total}} {{ $t("条账务记录继续保留，查询不会重新发放收益。") }}</p><form class="ufc-search" method="get"><input type="hidden" name="tab" value="history"><input name="history_search" :placeholder="$t(&quot;原 UID、Deepro 用户 ID 或账户编号&quot;)"><button>{{ $t("查找") }}</button></form><div class="ufc-scroll"><table><thead><tr><th>{{ $t("账户") }}</th><th>{{ $t("原 UID") }}</th><th>{{ $t("Deepro 用户") }}</th><th>{{ $t("总额度") }}</th><th>{{ $t("已用额度") }}</th><th></th></tr></thead><tbody><tr v-for="a in history.accounts?.data||[]" :key="a.id"><td>{{a.code}}</td><td>{{a.legacy_id||'—'}}</td><td>{{a.user_id||$t('待绑定')}}</td><td>{{fmt(a.quota_total)}}</td><td>{{fmt(a.quota_used)}}</td><td><a :href="historyUrl(a.id)">{{ $t("查看账务") }}</a></td></tr></tbody></table></div><div class="ufc-pages"><a v-if="history.accounts?.prev_page_url" :href="history.accounts.prev_page_url">{{ $t("上一页") }}</a><span>{{ $t("共") }} {{history.accounts?.total}} {{ $t("个账户") }}</span><a v-if="history.accounts?.next_page_url" :href="history.accounts.next_page_url">{{ $t("下一页") }}</a></div><div v-if="history.selected"><h3>{{history.selected.code}} {{ $t("· 账户余额") }}</h3><div class="ufc-scroll"><table><thead><tr><th>{{ $t("账户类别") }}</th><th>{{ $t("资产") }}</th><th>{{ $t("余额") }}</th></tr></thead><tbody><tr v-for="b in history.selected.balances" :key="b.pocket+b.asset"><td>{{ $t(historyPocket(b.pocket)) }}</td><td>{{b.asset}}</td><td>{{fmt(b.amount)}}</td></tr></tbody></table></div><h3>{{ $t("账务明细") }}</h3><div class="ufc-scroll"><table><thead><tr><th>{{ $t("记录") }}</th><th>{{ $t("资产") }}</th><th>{{ $t("变动") }}</th><th>{{ $t("余额") }}</th><th>{{ $t("说明") }}</th><th>{{ $t("日期") }}</th></tr></thead><tbody><tr v-for="e in history.selected.entries" :key="e.id"><td>{{e.id}}</td><td>{{e.asset}}</td><td>{{fmt(e.delta)}}</td><td>{{fmt(e.balance_after)}}</td><td>{{e.description}}</td><td>{{date(e.created_at)}}</td></tr></tbody></table></div><div class="ufc-pages"><a v-if="history.selected.entry_pagination?.prev" :href="history.selected.entry_pagination.prev">{{ $t("上一页") }}</a><span>{{ $t("共") }} {{history.selected.entry_pagination?.total}} {{ $t("条") }}</span><a v-if="history.selected.entry_pagination?.next" :href="history.selected.entry_pagination.next">{{ $t("下一页") }}</a></div></div><a href="/exchange-control-panel/umi/reconciliation">{{ $t("历史对账与规则核查 ›") }}</a></section>
