export default {mixins:[UmiLocale],components:{AdminLayout,LegacyAccounts,AccountHistory,UmiRecords,UmiMemberOverview},props:{capabilities:{type:Object,default:()=>({})},captureBatches:{type:Object,default:null},accountHistory:{type:Object,default:null},accountSection:{type:String,default:'overview'},state:{type:Object,required:true},initialTab:{type:String,default:'operations'},archive:{type:Object,default:null},history:{type:Object,default:null},cutover:{type:Object,default:null}},data(){return {selectedMember:null,captureCutoff:'',captureReason:'',data:this.state,cancelReasons:{},settingsRevision:this.state.settings_revision,tab:this.initialTab,busy:false,error:'',message:'',pendingIntent:null,memberSearch:this.state.member_search||'',legacyUserId:'',cutoverQuote:'',cutoverStart:'',cutoverConfirmed:false,accountCutoverEnabled:!!this.state.settings?.account_cutover_enabled,stockAction:'stock_transfer',stockFrom:'',stockTo:'',stockShares:'',stockReason:'',day:this.state.settlement_calendar?.next_day||'',rate:this.state.settings?.settlement_rate||'0.01',dayRate:this.state.settlement_calendar?.rate||'0.01',poolUserId:this.state.settings?.pool_user_id||'',dedicatedAddress:this.state.settings?.dedicated_address||'',intakeEnabled:!!this.state.settings?.intake_enabled,settlementEnabled:!!this.state.settings?.settlement_enabled,withdrawalEnabled:!!this.state.settings?.withdrawal_enabled,stockTransferEnabled:!!this.state.settings?.stock_transfer_enabled,asset:'HK08379_USDT',price:'',source:'',sourceRef:'',observedAt:'',tabs:[{key:'records',label:this.$t("完整记录 / 用户全景")},{key:'cutover',label:this.$t("本金接续")},{key:'archive',label:this.$t("账户管理")},{key:'history',label:this.$t("账务记录")},{key:'operations',label:this.$t("运营")},{key:'burn',label:this.$t("销毁")},{key:'members',label:this.$t("用户")},{key:'stock',label:this.$t("参考份额权益")},{key:'orders',label:this.$t("订单")},{key:'settings',label:this.$t("配置")}]};},computed:{visibleTabs(){return this.tabs.filter(t=>!(['archive','cutover'].includes(t.key)&&!this.capabilities.legacy)&&!(t.key==='settings'&&!this.capabilities.settings&&!this.capabilities.quotes));}},methods:{canAction(action){const caps={settings:'settings',quote:'quotes',spot_quote:'quotes',day:'settlement',queue_burn:'burn',sync_burn:'burn',recover_points:'burn',cancel_intake:'orders',activate_legacy:'legacy',approve_snapshot:'legacy',account_cutover:'legacy',stock_settle:'stock',stock_transfer:'stock',stock_writeoff:'stock'};return !!this.capabilities[caps[action]];},captureIssue(v){return {identity:this.$t('身份未核定'),duplicate_identity:this.$t('身份重复'),legacy_identity:this.$t('原账户绑定不一致'),missing_snapshot_account:this.$t('采集批次缺少该账户'),missing_business_account:this.$t('尚未建立对应业务账户'),negative_balance:this.$t('存在负余额'),non_umi_balance:this.$t('非 UMI 余额需单独核对'),parent_identity:this.$t('原上级关系不一致')}[v]||(v.startsWith('balance:')?this.$t('余额分项不一致：')+this.historyPocket(v.slice(8)):v);},selectTab(key){if(this.busy||this.pendingIntent){this.error=this.$t('请先确认当前操作结果后再切换页面。');return;}if(['cutover','archive','history'].includes(key)){this.$inertia.visit('/exchange-control-panel/umi/operations?tab='+encodeURIComponent(key));return;}this.tab=key;const u=new URL(window.location.href);u.searchParams.set('tab',key);window.history.replaceState({},'',u);},historyPocket(v){return {main:this.$t('可用余额'),linear:this.$t('理财收益'),team:this.$t('团队收益'),referral:this.$t('推荐收益'),treasure:this.$t('UMI 宝'),reserve:this.$t('储备金'),vip:this.$t('质押'),unstaking:this.$t('解锁中'),points:this.$t('股票积分')}[v]||v;},historyUrl(id){return '/exchange-control-panel/umi/operations?tab=history&history_account='+id;},fmt:formatUmi,date(value){return umiTime(value,this.$i18n.locale);},stockStatus(v){return {points_only:this.$t('待确权'),locked:this.$t('已确权 · 锁定中'),tradable:this.$t('可划转')}[v]||v;},stockMove(v){return {entitlement:this.$t('确权'),unlock:this.$t('解锁'),transfer:this.$t('划转'),write_off:this.$t('核销'),exchange_transfer:this.$t('转入 Deepro')}[v]||v;},searchMembers(){window.location.href='/exchange-control-panel/umi/operations?member_search='+encodeURIComponent(this.memberSearch);},purpose(v){return {activation:this.$t('充值'),withdrawal:this.$t('提现'),injury:this.$t('超额')}[v]||v;},issue(v){return {funded_release_disabled:this.$t('正式入口未开启'),pool_account_missing:this.$t('资金池账户'),bsc_network_missing:this.$t('BSC 网络'),dedicated_address_missing:this.$t('专属销毁发送地址'),wallet_or_asset_unavailable:this.$t('现货钱包或 BSC 资产配置'),bsc_asset_mismatch:this.$t('UMI 合约'),verified_deposit_unavailable:this.$t('UMI 充值通道'),custody_unavailable:this.$t('托管通道'),custody_sender_invalid:this.$t('托管地址'),dedicated_sender_mismatch:this.$t('专属地址与实际托管发送地址不一致'),local_history_requires_isolation:this.$t('本地测试数据隔离')}[v]||v;},key(){return window.crypto?.randomUUID?.()||'umi-'+Date.now()+'-'+Math.random().toString(36).slice(2);},async send(action,fields){if(!this.canAction(action)){this.error=this.$t('没有此操作权限。');return;}this.error='';this.message='';this.busy=true;this.pendingIntent=prepareIntent(this.pendingIntent,action,fields,()=>this.key());try{const r=await axios.post('/exchange-control-panel/umi/operations',{action,request_key:this.pendingIntent.key,...fields});this.data=r.data.state;this.pendingIntent=null;if(action==='settings')this.settingsRevision=this.data.settings_revision;this.day=this.data.settlement_calendar?.next_day||'';this.dayRate=this.data.settlement_calendar?.rate||'0.01';if(['approve_snapshot','account_cutover'].includes(action)){window.location.reload();return;}this.message=action==='account_cutover'?this.$t('接续已完成，请刷新核对账户与账务记录。'):this.$t('操作已记录。');}catch(e){if(!retainIntentAfterError(e))this.pendingIntent=null;this.error=Object.values(e.response?.data?.errors||{}).flat().join('；')||e.response?.data?.message||this.$t('操作未完成，请检查记录后重试。');}finally{this.busy=false;}}}};
</script>
